            stats.incrementCount(actor.getActorType());
            fieldView.drawMark(col, row, getColor(actor.getActorType()));
        });
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

